  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://archive.com/blog/medicube-influencer-marketing-strategy', 'creator_report', 'affiliate', 'Archive''s breakdown of Medicube''s creator strategy reports up to 30% commission rates on TikTok Shop across 101 SKUs, with free samples and a dedicated creator app; no cap on earnings is stated in any source checked, so the cap is recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://archive.com/blog/medicube-influencer-marketing-strategy', 'creator_report', 'creator_saturation', 'Archive counts 33,900+ active creator affiliates and 25,700 sponsored posts in 12 months for Medicube — clear evidence of HIGH creator saturation, the opposite of the low-saturation filter.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://medicube.us/pages/ambassador_test', 'official_site', 'ugc_collab', 'Medicube''s official ambassador page (shared with APRILSKIN) invites creators to browse campaigns with guidelines, timelines and reward details, submit photos or videos, and track rewards and payments; members receive bestsellers and new releases and a guaranteed reward for every approved submission. Snippet''s November 2026 check lists hello@medicube.us as the brand''s published contact for the program.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 20, 18, 12, 9, 5, '{"niche_fit": "K-beauty skincare plus beauty devices \u2014 the centre of the skincare UGC niche, with highly demonstrable products.", "ugc_evidence": "The strongest creator evidence in this round: a 33,900+ creator affiliate base, 25,700 sponsored posts in 12 months, and a structured ambassador program with per-submission rewards.", "compensation": "Up to 30% TikTok Shop commission reported by Archive \u2014 the highest rate in this round; ambassador rewards are additional but not priced publicly.", "contact_access": "Published program email (hello@medicube.us) plus an in-nav ambassador application page on the brand''s own store.", "opportunity_availability": "Ambassador applications are open with no follower minimum recorded; TikTok Shop affiliate access is open to eligible creators.", "credibility": "One of the largest K-beauty brands in the US market, with 1M+ TikTok Shop units sold and celebrity-level creator partnerships."}'::jsonb);
