  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Gisou Affiliate Program (LTK / ShopMy / Impact)', 'https://gisou.com/pages/affiliate-program', 'https://gisou.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://gisou.com/pages/affiliate-program', 'official_site', 'affiliate', 'Gisou''s official affiliate page states affiliates earn up to 15% commission on a cost-per-sale basis via tracking link, joining through LTK or ShopMy (recommended for creators) or Impact (websites and publishers), with Impact partner approval in 3-5 business days. The page answers ''How much can I earn?'' with the rate only — no statement about a cap on total earnings, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://gisou.com/pages/affiliate-program', 'official_site', 'ugc_collab', 'The program is explicitly ''made for loyal fans and creators'' and pays commission rather than gifting; ShopMy is recommended for new or established creators, and creators can promote any Gisou product with reporting in their platform dashboard.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 17, 16, 11, 8, 5, '{"niche_fit": "Creator-founded, visually driven hair and lip care \u2014 squarely in the beauty UGC niche.", "ugc_evidence": "A dedicated creator affiliate program across three creator platforms, with ShopMy actively recommended for new creators.", "compensation": "Up to 15% cost-per-sale commission published on the brand''s own page; no cap statement is published, so the cap stays unknown.", "contact_access": "A defined application route through LTK, ShopMy or Impact from the official page; no direct program email is published.", "opportunity_availability": "Open to creators and publishers on the three platforms; platform approval typically 1-3 days, Impact partner approval 3-5 business days.", "credibility": "Globally recognised, influencer-founded beauty brand with major retail presence and a formal affiliate page."}'::jsonb);
