  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Kindness Krew Creator & Affiliate Program', 'https://beekman1802.com/pages/kindness-krew', 'https://beekman1802.com/pages/kindness-krew', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://partners.beekman1802.com/account/terms', 'official_site', 'affiliate', 'Beekman 1802''s official Kindness Krew terms state ambassadors earn 8% commission on all valid sales made through their discount code or link, plus a $75 product credit every three months, with commission paid via PayPal 45 days after the sale; Glossy reports tier commission levels ranging 8-12%. No cap on earnings is stated in the terms, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://beekman1802.com/pages/kindness-krew', 'official_site', 'ugc_collab', 'The official Kindness Krew page runs two open application tracks: a Creator track (1,000+ followers on Instagram and TikTok, one in-feed post and one story per month, open to being featured across brand channels) and an Affiliate track with no follower minimum for everyday social users and aspiring creators; both are 18+ and US-based.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 17, 11, 12, 9, 5, '{"niche_fit": "Goat-milk skincare with a strong education and routine angle for skincare creators.", "ugc_evidence": "A structured, always-on ambassador program with posting requirements, tier progression and brand reuse of member content \u2014 a genuine creator program, not just a link scheme.", "compensation": "8% base commission in the official terms (tiers reported up to 12%) plus a $75 quarterly product credit; modest rate, no cap statement published.", "contact_access": "Two direct application links published on the brand''s own program page, one per track.", "opportunity_availability": "Affiliate track has no follower minimum; creator track starts at 1,000 followers \u2014 among the most accessible programs in this round.", "credibility": "Established US skincare brand with a formal, terms-backed ambassador program running since 2024."}'::jsonb);
