  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://beautyofjoseon.com/pages/affiliate-terms', 'official_site', 'affiliate', 'Beauty of Joseon''s official Affiliate Terms state the program is joined by application through Shopify Collabs and that commission is ''the rate agreed in writing between us and you'' in each Offer, paid on the net sales amount in US dollars — no public percentage is published anywhere in the terms, so the commission rate is recorded as null. No cap on earnings is stated either, so the cap is recorded as unknown.', 'verified', now());
