  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 11, 15, 8, 6, 4, '{"niche_fit": "Clean, luxury-positioned skincare and fragrance aimed squarely at beauty creators'' audiences.", "ugc_evidence": "Active creator gifting and a GRIN presence, but no open published creator program on the brand''s own channels \u2014 evidence is thinner than for the Collabs/ambassador brands in this round.", "compensation": "Up to 15% per the Lasso listing \u2014 attractive if confirmed at sign-up; not published on the brand''s own site, so scored with that caution.", "contact_access": "Affiliate listing route plus a GRIN proposal route; no published program email.", "opportunity_availability": "Gifting is active for ~500+ follower creators, but the lack of a published open program lowers availability.", "credibility": "Established clean-beauty brand with Ulta online distribution."}'::jsonb);
