  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkapprove.com/affiliate-programs/anua-affiliate-program', 'affiliate_directory', 'affiliate', 'LinkApprove''s Anua program page (reviewed October 22, 2026) states the program pays 8.4% per sale on a 30-day cookie window for US orders from Anua''s own US store, is free to join from 1,000 followers, and needs no separate Anua application because LinkApprove holds the upstream approval. No cap on earnings is stated, so the cap is recorded as unknown.', 'publicly_reported', now());
