  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 11, 10, 7, 8, 4, '{"niche_fit": "Viral K-beauty staples (heartleaf toner and cleansing oil) built for double-cleansing and sensitive-skin routines.", "ugc_evidence": "Heavy TikTok Shop creator activity and an #anuambassador presence, but no brand-run program page \u2014 evidence rests on the network listing.", "compensation": "8.4% per sale on the brand''s own US store per LinkApprove \u2014 mid-range; no cap statement published.", "contact_access": "No brand application or program email exists publicly; access is only through the LinkApprove partner account.", "opportunity_availability": "Free to join via LinkApprove from 1,000 followers with decisions usually within two business days, US traffic only.", "credibility": "Established K-beauty brand with Amazon and K-beauty retail best-sellers."}'::jsonb);
