  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/vegamour/', 'affiliate_directory', 'affiliate', 'Lasso''s Vegamour program page states up to 8% per sale with a 15-day cookie and a $50 payout threshold, and its join link routes to CJ Affiliate signup; LinkClicky''s program listing independently records 8% per sale. No cap on earnings is stated in either listing, so the cap is recorded as unknown.', 'publicly_reported', now());
