  insert into public.brands (name, website, description, country, status) values ('SQUATWOLF', 'https://squatwolf.com', 'Dubai-born premium gym and performance-wear brand for men and women, founded by Anam and Wajdan with the stated aim of building the first global apparel brand from the Middle East. In January 2026 it launched its first formal global affiliate programme on CJ Affiliate, aimed at content creators and gym communities.', 'United Arab Emirates', 'published') returning id into bid;
