  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'CJ Affiliate', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: low (see evidence). Rate as reported by https://www.Shopper.com/partnerships/squatwolf-com-affiliate-program.', 'https://www.Shopper.com/partnerships/squatwolf-com-affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'SQUATWOLF Affiliate Program (CJ Affiliate)', 'https://www.Shopper.com/partnerships/squatwolf-com-affiliate-program', 'https://campaignme.com/how-squatwolf-aims-to-set-the-middle-east-affiliate-marketing-standard/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://campaignme.com/how-squatwolf-aims-to-set-the-middle-east-affiliate-marketing-standard/', 'listing', 'affiliate', 'Campaign Middle East (22 Jan 2026) reports SQUATWOLF ''is launching its first ever global affiliate marketing network programme'' on the CJ Affiliate (CJ) network, led by its E-commerce and Digital Director and aimed at a curated publisher ecosystem including content creators and gym communities; the brand calls it ''our first strong rep towards that'' — a brand-new programme, which is the basis for the low-saturation mark.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.Shopper.com/partnerships/squatwolf-com-affiliate-program', 'listing', 'affiliate', 'Shopper''s SQUATWOLF partnership listing states ''The Squatwolf affiliate program offers a payout rate of 5%'' and describes the brand as ''Premium Gym Wear, Born & Designed in Dubai, UAE''; CompareEPC''s activewear table independently lists SQUATWOLF on CJ at 5%. No cap statement is published anywhere fetched, so the cap is honestly unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://squatwolf.com/en-ae/pages/our-story', 'official_site', 'ugc_collab', 'SQUATWOLF''s official Our Story page describes the brand being built in Dubai by founders Anam and Wajdan, ''building the first global apparel brand from the Middle East'' from a small Dubai apartment.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 8, 7, 9, 4, '{"compensation": "5% per sale per two independent listings \u2014 modest but published; no cap statement anywhere, so the cap is unknown.", "contact_access": "Joining runs through the CJ programme listing; no published partnerships email was verified on a fetched page.", "credibility": "Established Dubai premium activewear brand covered by trade press for its affiliate launch.", "niche_fit": "Premium gym apparel for men and women \u2014 squarely in the fitness-creator niche.", "opportunity_availability": "The programme launched in January 2026 and is actively recruiting its first publisher cohort.", "ugc_evidence": "A formal affiliate programme explicitly courting content creators and gym communities, though only just launched."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Bells of Steel', 'https://bellsofsteel.com', 'Canadian-founded strength-equipment retailer established in 2010 by Kaevon Khoozani, selling power racks, barbells, plates, benches, cable machines and kettlebells for home gyms in Canada and the US. Its own affiliate programme terms state the program is intended for content creators and fitness influencers.', 'Canada', 'published') returning id into bid;
