  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Bells of Steel Affiliate Program', 'https://bellsofsteel.postaffiliatepro.com/affiliates/terms-conditions.php', 'https://bellsofsteel.postaffiliatepro.com/affiliates/terms-conditions.php', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://bellsofsteel.postaffiliatepro.com/affiliates/terms-conditions.php', 'official_site', 'affiliate', 'The brand''s own affiliate portal terms state ''This program is intended for actual content creators and fitness influencers''; affiliates must have PayPal, payouts are monthly with a $100 minimum balance, and coupon sites and dropshippers are not permitted. The portal publishes terms but no commission percentage, and no cap statement, so the cap is honestly unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://compareepc.com/health-affiliate-programs/', 'listing', 'affiliate', 'CompareEPC''s affiliate database lists Bells Of Steel on Impact at 5% commission with a $5.31 EPC — the only published rate found; Sovrn''s merchant page states its own rate ''could not be independently verified'', so the 5% is recorded as publicly reported, not brand-published.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://merchants.sovrn.com/merchants/238442/bells-of-steel-affiliate-program', 'listing', 'ugc_collab', 'Sovrn describes Bells of Steel as a Canadian-founded strength-equipment retailer established in 2010 by Kaevon Khoozani, with operations serving Canada and the United States; the brand''s official About page says it grew from selling competition-grade kettlebells from a car trunk to a team of 80.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 8, 10, 8, 4, '{"compensation": "5% per the only published listing (CompareEPC, via Impact); the brand''s own portal publishes no rate, so this stays low-mid.", "contact_access": "Published support and commercial emails on official pages plus the brand''s own affiliate portal \u2014 good access, though no dedicated partnerships email.", "credibility": "Founded in 2010 with Canada and US operations and a team of 80 per its official About page.", "niche_fit": "Home-gym strength equipment is a core, fast-growing fitness-creator niche.", "opportunity_availability": "Applications are open through the brand''s own affiliate portal today.", "ugc_evidence": "Official programme terms explicitly target content creators and fitness influencers, with clear payout rules."}'::jsonb);
