  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 11, 6, 5, 4, '{"compensation": "8% per the Skimlinks listing in CompareEPC''s database \u2014 published, though not on the brand''s own site.", "contact_access": "Only a customer-service email is published; no partnerships email or application page was verified.", "credibility": "Established Swedish DTC activewear brand selling in 120 countries.", "niche_fit": "Women''s activewear is a core fitness-fashion creator niche.", "opportunity_availability": "No direct brand signup page was found; access runs through the Skimlinks listing, so availability scores low.", "ugc_evidence": "A long-standing influencer/ambassador model with UGC integrated into its storefront, but the affiliate route is listing-only."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('YoungLA', 'https://www.youngla.com', 'Los Angeles-based fitness, streetwear and lifestyle apparel brand founded in 2014 by brothers Garry and Robby Chopra, with a women''s line (YoungLA for Her, launched 2022). CreatorIQ describes it as an affiliate-driven DTC fitness apparel brand whose top creators share personalised discount codes and affiliate links.', 'United States', 'published') returning id into bid;
