  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, null, null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.creatoriq.com/blog/youngla-influencer-marketing-growth?hs_amp=true.', null, 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.creatoriq.com/blog/youngla-influencer-marketing-growth?hs_amp=true', 'listing', 'affiliate', 'CreatorIQ''s research (Mar 2025) reports: ''Affiliate codes are a hallmark of YoungLA''s top-performing content... In 2024, posts mentioning an affiliate code powered $245.7M EMV — more than half of YoungLA''s $431.7M EMV total.'' No commission percentage is published anywhere fetched, so the rate is recorded as null and the cap as unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.creatoriq.com/blog/youngla-influencer-marketing-growth?hs_amp=true', 'listing', 'ugc_collab', 'The same CreatorIQ study states: ''Of all the 100 brands on that list, YoungLA claimed, by far, the smallest creator count'' despite ranking No. 50 for total engagements in 2024 — 2.3K creators in 2024, with 669 core creators powering $284.8M EMV. That published creator count, the smallest among peer top-100 engagement brands, is the basis for the low-saturation mark; the absolute core cohort is still in the hundreds.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.youngla.com/pages/about-us', 'official_site', 'ugc_collab', 'YoungLA''s official About Us page states it was founded in Los Angeles in 2014, describes ''a global fitness and lifestyle brand reaching millions through our products, athletes, creators'', publishes a questions phone number, and links its Instagram (instagram.com/youngla) and TikTok (tiktok.com/@youngla) profiles. No public affiliate application page or email is published on the fetched official pages.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.creatoriq.com/blog/youngla-influencer-marketing-growth?hs_amp=true', 'creator_report', 'creator_saturation', 'Creator saturation re-judged to ''unknown'' by the batch coordinator: the CreatorIQ figure (2.3K creators in 2024, smallest on its 100-brand engagement list) is a relative mark; by the standard applied across batches (492 creators judged too high to call low), 2.3K creators is not verified-low in absolute terms.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 19, 4, 5, 4, 5, '{"compensation": "No commission rate is published anywhere fetched, so this stays low per the rubric despite the programme''s scale.", "contact_access": "No public application page or published partnerships email; only a phone number on the official About page.", "credibility": "Major DTC fitness apparel brand with $431.7M earned media value in 2024 per CreatorIQ.", "niche_fit": "Fitness and streetwear apparel is a top creator niche, with a women''s line since 2022.", "opportunity_availability": "The programme runs on personalised creator codes with no public application route found, so availability scores low.", "ugc_evidence": "One of the most documented creator-affiliate models in fitness: affiliate-code posts powered over half of the brand''s 2024 EMV."}'::jsonb);
