  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://alohas.com/en-us/pages/affiliates', 'official_site', 'affiliate', 'ALOHAS'' official affiliates page (''JOIN ALOHAS AFFILIATE PROGRAM'') states affiliates ''enjoy exclusive perks, including up to 15% CPA for tailored campaigns, complimentary ALOHAS products to test'', alongside ''10% Average CPA managed'', ''+395 Facilitated orders'', ''+$9,000 Earned in commissions'' and ''$174 AOV Achieved''.', 'verified', now());
