  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.klaviyo.com/customers/case-studies/kulani-kinis', 'listing', 'ugc_collab', 'Klaviyo''s case study reports ''130K global members of brand ambassador program'', grown ''more than 5x in less than 4 years'', plus ''4.8K+ user-generated social posts tagging the brand in past year'' — the basis for the high-saturation mark. The same page describes Kulani Kinis as a DTC-first swimwear brand founded by Alex Babich and Dani Atkins in Sydney in 2015.', 'publicly_reported', now());
