  insert into public.brands (name, website, description, country, status) values ('Osprey', 'https://www.osprey.com', 'Backpack and travel-gear brand born in California in 1974, making innovative packs and travel accessories used from mountains to islands. Its Awin programme pays a dedicated 10% tier to content and influencer partners, above its standard 5% new-customer and 3% existing-customer rates.', 'United States', 'published') returning id into bid;
