  insert into public.brands (name, website, description, country, status) values ('Db Journey', 'https://dbjourney.com', 'Scandinavian travel-gear brand founded in Norway in 2009 by freeski legend Jon Olsson and engineer Truls Brataas, headquartered in Oslo, making bags and gear ''designed for life on the move'' for photographers, commuters and travellers. Its Awin listing runs a combined Affiliate & Ambassador Program with product samples and perks for creators.', 'Norway', 'published') returning id into bid;
