  insert into public.brands (name, website, description, country, status) values ('Knack Bags', 'https://knackbags.com', 'Maker of innovative expandable backpacks with a patented expanding design, built to adapt from work to life for professionals, travellers and everyday adventurers carrying everything in a single bag. Its affiliate programme runs on Impact at a published 8% per sale.', null, 'published') returning id into bid;
