  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/knack-bags/', 'listing', 'affiliate', 'LinkClicky''s Knack Bags listing gives: website knackbags.com, platform Impact, regions ALL, commission ''8% per sale, $0.25 Email per signup''; its FAQ repeats ''The commission rate for Knack Bags is 8% per sale'' and ''Knack Bags uses the Impact affiliate platform''. A separate Lasso listing claims up to 15% — flagged as a conflict; the Impact listing''s 8% is the recorded rate. No cap statement is published, so the cap is honestly unknown.', 'publicly_reported', now());
