  insert into public.brands (name, website, description, country, status) values ('Nushape', 'https://www.nushape.com/', 'Wearable wellness-device brand founded in 2015 by Jessica Charles, selling red light therapy, PEMF and molecular hydrogen belts, wraps and mats for recovery, sleep and body sculpting, with affiliate and referral programs that pay cash for referred purchases.', null, 'published') returning id into bid;
