  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin / Social Snowball', 5, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/46925.', 'https://www.nushape.com/pages/affiliates-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Nushape Affiliate & Referral Program', 'https://www.nushape.com/pages/affiliates-program', 'https://www.nushape.com/pages/affiliates-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.nushape.com/pages/affiliates-program', 'official_site', 'affiliate', 'Nushape''s official affiliates page runs a referral program paying a flat $50 cash for each referral that completes a purchase, paid via PayPal in the first week of the following month. Its FAQ answers the question ''Is there a limit to how much I can earn?'' with ''There is no limit to the amount you can earn'' (new-customer referrals only, self-referrals excluded), so the commission cap is recorded as uncapped. Top partners unlock ambassador status after 10 referral sales, with free product and increased commissions.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/46925', 'official_site', 'affiliate', 'Nushape''s Awin merchant profile for the Nushape LLC Affiliate Program offers a 5% referral fee for orders coming through an affiliate link, with a 30-day cookie and in-house affiliate management, and publishes hello@nushape.com as the program contact. The profile notes the program also runs on Social Snowball/ShareASale and voids double-attributed transactions.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.nushape.com/pages/asi', 'official_site', 'general', 'Nushape''s partner page describes the brand as a trailblazer in red light therapy founded by Jessica Charles in 2015, making wearable red light, PEMF and molecular hydrogen devices (belts, mats, wraps and the NeuroWrap), and quotes a 10% commission for hospitality/spa partners — a third, partner-specific figure, so the consumer affiliate rate used here is the Awin-published 5%.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 13, 10, 9, 4, '{"compensation": "The Awin rate is a modest 5%, but the in-house referral program pays a flat $50 per completed purchase on high-ticket devices, and the official FAQ states there is no limit on earnings.", "contact_access": "Instant enrollment on the brand''s own page plus a published program email (hello@nushape.com) on its Awin profile.", "credibility": "Operating since 2015 with a distinctive wearable-device line and programs listed on a major network (Awin).", "niche_fit": "Wearable red light and PEMF devices sit squarely in the recovery, sleep and biohacking content wellness creators already make.", "opportunity_availability": "Anyone can join the referral program today and share a link immediately; the Awin program is also open for application.", "ugc_evidence": "An open referral program explicitly aimed at influencers, doctors and fans, plus an ambassador tier that rewards top partners with free product and higher commissions."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Earthley', 'https://www.earthley.com/', 'Family-owned natural-remedies brand based in Columbus, Ohio, selling herbal tinctures, powders, salves, soaps and personal-care products made with fully disclosed 100% natural ingredients, and running an ''Earthologist'' affiliate program alongside a practitioner wholesale program.', 'United States', 'published') returning id into bid;
