  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Earthley Earthologist Affiliate Program', 'https://www.earthley.com/affiliate-and-wholesale-programs', 'https://www.earthley.com/affiliate-and-wholesale-programs', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.earthley.com/affiliate-and-wholesale-programs', 'official_site', 'affiliate', 'Earthley''s official affiliate page states its Earthologist program pays 15% commission on all sales including personal orders; its FAQ confirms commission starts at 15% and is bumped to 20% after the first $1,000 in sales, paid via PayPal or store credit. No fetched source states any cap on earnings, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.earthley.com/affiliate-and-wholesale-programs', 'official_site', 'ugc_collab', 'The same official page describes affiliate perks aimed at creators — a support Facebook group, sales and marketing training, early access to new products and product testing before release — and publishes earthologists@earthley.com for affiliate inquiries. The business is family-owned and based in Columbus, OH.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 27, 14, 17, 13, 9, 4, '{"compensation": "15% on all sales from day one, rising to 20% after $1,000 in sales \u2014 among the better published base rates in natural remedies.", "contact_access": "Open sign-up from the official page and a published affiliate-team email (earthologists@earthley.com).", "credibility": "Family-owned US business with its own retail store, cGMP-certified and FDA-inspected manufacturing, and fully disclosed ingredients.", "niche_fit": "Herbal tinctures and clean family remedies are core natural-health creator content with strong everyday-use storytelling.", "opportunity_availability": "Applications are open now; anyone with an Earthley account can apply.", "ugc_evidence": "A named affiliate community (Earthologists) with training, a support group, contests and early product access for partners."}'::jsonb);
